#include <iostream>
#include <map>
#include <set>
#include <utility>
#include <vector>
using namespace std;

int main() {
  cin.tie(0)->sync_with_stdio(0);
  int N;
  cin >> N;
  vector<int> X(N), R(N);
  for (int i = 0; i < N; i++) cin >> X[i] >> R[i];

  map<int, vector<pair<int, int>>> g;
  for (int i = 0; i < N; i++) {
    int xpr = X[i] + R[i];
    int xmr = X[i] - R[i];
    g[xpr].emplace_back(xmr, i);
    g[xmr].emplace_back(xpr, i);
  }

  set<int> visited;
  auto dfs = [&](auto rc, int c, int edge_num) -> pair<int, int> {
    visited.insert(c);
    int num = 1;
    int is_tree = true;
    for (auto& [d, e] : g[c]) {
      if (e == edge_num) continue;
      if (visited.count(d)) {
        is_tree = false;
      } else {
        auto [n, f] = rc(rc, d, e);
        num += n;
        is_tree &= f;
      }
    }
    return make_pair(num, is_tree);
  };

  int ans = 0;
  for (auto& [key, _] : g) {
    if (visited.count(key)) continue;
    auto [num, is_tree] = dfs(dfs, key, -1);
    ans += is_tree ? num - 1 : num;
  }
  cout << ans << "\n";
}

#include <iostream>
#include <set>
#include <utility>
#include <vector>
using namespace std;
#include "atcoder/maxflow.hpp"

int main() {
  cin.tie(0)->sync_with_stdio(0);
  int N;
  cin >> N;
  vector<int> X(N), R(N);
  for (int i = 0; i < N; i++) cin >> X[i] >> R[i];

  set<int> st;
  for (int i = 0; i < N; i++) {
    int xpr = X[i] + R[i];
    int xmr = X[i] - R[i];
    st.insert(xpr), st.insert(xmr);
  }

  vector<int> coords;
  for (auto& s : st) coords.push_back(s);
  int M = coords.size();

  int source = N + M;
  int sink = source + 1;
  atcoder::mf_graph<int> g(sink + 1);

  for (int i = 0; i < N; i++) {
    g.add_edge(source, i, 1);
  }
  for (int i = 0; i < N; i++) {
    int xpr = X[i] + R[i];
    int xmr = X[i] - R[i];
    xpr = lower_bound(begin(coords), end(coords), xpr) - begin(coords);
    xmr = lower_bound(begin(coords), end(coords), xmr) - begin(coords);
    g.add_edge(i, N + xpr, 1);
    g.add_edge(i, N + xmr, 1);
  }
  for (int j = 0; j < M; j++) {
    g.add_edge(N + j, sink, 1);
  }

  cout << g.flow(source, sink) << "\n";
}
